#include "ERA5DeClipperCore.hpp"
#include <iostream>
#include <iomanip>
#include <limits>
#include <new>
#include <string_view>
static bool tracking=false;static uint64_t allocations=0;
void*operator new(std::size_t n){if(tracking)++allocations;if(void*p=std::malloc(n))return p;throw std::bad_alloc();}
void*operator new[](std::size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}
static float source(uint32_t i,double rate,unsigned ch,bool poison){double t=i/rate;double x=.7*std::sin(2*M_PI*(ch?811:997)*t)+.2*std::sin(2*M_PI*301*t);x=std::clamp(x,-.15,.25);float y=float(x);if(poison){if(i%7919==11)y=std::numeric_limits<float>::quiet_NaN();if(i%6151==31)y=std::numeric_limits<float>::infinity();if(i%6553==17)y=-3e35f;}return y;}
static uint64_t hash(const std::vector<float>&v){uint64_t h=1469598103934665603ull;for(unsigned char c:std::string_view(reinterpret_cast<const char*>(v.data()),v.size()*4)){h^=c;h*=1099511628211ull;}return h;}
struct Result{std::vector<float>output;uint64_t deadlines=0,hash=0;bool finite=true;};
static Result render(double rate,uint32_t frames,uint32_t block,unsigned channels,int quality,bool poison,bool automation,bool resetFirst=false,bool bypass=false){dayu::ERA5DeClipperCore core;core.prepare(rate);core.setParameter(2,1);core.setParameter(0,float(quality));core.setBypass(bypass);core.reset();std::array<std::vector<float>,2>in,out;for(auto&v:in)v.resize(4096);for(auto&v:out)v.resize(4096);float*pi[2]={in[0].data(),in[1].data()},*po[2]={out[0].data(),out[1].data()};if(resetFirst){for(unsigned c=0;c<channels;++c)for(unsigned i=0;i<1024;++i)pi[c][i]=.3f;core.process(pi,po,channels,1024);core.reset();}Result r;r.output.resize(size_t(frames)*channels);for(uint32_t t=0;t<frames;){if(automation&&t==1000)core.rampParameter(3,-8,997);if(automation&&t==3000)core.setParameter(4,0);if(automation&&t==5000)core.setParameter(4,1);if(automation&&t==7000)core.setBypass(true);if(automation&&t==9000)core.setBypass(false);uint32_t n=std::min(block,frames-t);if(automation)for(uint32_t event:{1000,3000,5000,7000,9000})if(event>t)n=std::min(n,event-t);for(unsigned c=0;c<channels;++c)for(uint32_t i=0;i<n;++i)pi[c][i]=source(t+i,rate,c,poison);tracking=true;core.process(pi,po,channels,n);tracking=false;for(unsigned c=0;c<channels;++c)for(uint32_t i=0;i<n;++i){r.output[size_t(c)*frames+t+i]=po[c][i];r.finite=r.finite&&std::isfinite(po[c][i]);}t+=n;}r.deadlines=core.deadlineMisses();r.hash=hash(r.output);return r;}
int main(int argc,char**argv){const bool brief=argc>1;bool ok=true;std::cout<<"{\"tests\":[";bool comma=false;auto record=[&](const char*name,bool pass,uint64_t h=0,uint64_t d=0){if(comma)std::cout<<",";comma=true;std::cout<<"{\"name\":\""<<name<<"\",\"pass\":"<<(pass?"true":"false")<<",\"hash\":\""<<std::hex<<h<<std::dec<<"\",\"workDeadlineMisses\":"<<d<<"}";ok=ok&&pass;};
const uint32_t length=brief?24000:144000;auto base=render(48000,length,512,2,0,true,true);record("48k-type2-standard-finite",base.finite,base.hash,base.deadlines);
for(uint32_t block:{1u,31u,257u,4096u}){auto b=render(48000,length,block,2,0,true,true);record(("block-"+std::to_string(block)).c_str(),b.finite&&base.output==b.output&&b.deadlines==0,b.hash,b.deadlines);}
auto reset=render(48000,length,127,2,0,true,true,true);record("reset-clears-inflight",base.output==reset.output,reset.hash,reset.deadlines);
auto mono=render(48000,length,193,1,0,true,false);record("mono-finite",mono.finite,mono.hash,mono.deadlines);
auto high=render(48000,brief?24000:96000,512,2,1,true,false);record("high-quality-finite",high.finite,high.hash,high.deadlines);
for(double rate:{16000.,44100.,96000.,384000.}){auto b=render(rate,uint32_t(rate*(brief?.2:.35)),511,2,0,true,false);record(("rate-"+std::to_string(int(rate))).c_str(),b.finite&&b.deadlines==0,b.hash,b.deadlines);}
auto dry=render(48000,24000,512,1,0,true,false,false,true);bool dryOk=true;const auto latency=dayu::ERA5DeClipperCore::latencyFramesForRate(48000);for(uint32_t i=0;i<24000;++i){float expected=0;if(i>=latency){expected=source(i-latency,48000,0,true);if(!std::isfinite(expected))expected=0;expected=std::clamp(expected,-64.f,64.f);}if(dry.output[i]!=expected){dryOk=false;break;}}record("bypass-fixed-latency",dryOk,dry.hash,dry.deadlines);
record("parameter-sanitization",dayu::ERA5DeClipperCore::sanitize(3,std::numeric_limits<float>::quiet_NaN())==0&&dayu::ERA5DeClipperCore::sanitize(3,100)==5&&dayu::ERA5DeClipperCore::sanitize(99,100)==0);record("sample-rate-negotiation",!dayu::ERA5DeClipperCore::supportsRate(8000)&&dayu::ERA5DeClipperCore::supportsRate(16000)&&dayu::ERA5DeClipperCore::supportsRate(384000));record("render-zero-new",allocations==0);std::cout<<"],\"pass\":"<<(ok?"true":"false")<<",\"renderAllocations\":"<<allocations<<"}\n";return ok?0:1;}
